import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    P_counts = Counter(int(x) for x in input_data[2:2+N])
    unique_P = sorted((p, count) for p, count in P_counts.items())

    low = 0
    high = 2_000_000_000_000_000_000
    ans_X = 0

    while low <= high:
        mid = (low + high) // 2
        total_cost = 0
        possible = True

        for p, count in unique_P:
            if p > mid:
                break
            k = (mid // p + 1) // 2
            total_cost += k * k * p * count

            if total_cost > M:
                possible = False
                break

        if possible:
            ans_X = mid
            low = mid + 1
        else:
            high = mid - 1

    total_cost = 0
    total_items = 0
    for p, count in unique_P:
        if p > ans_X:
            break
        k = (ans_X // p + 1) // 2
        total_items += k * count
        total_cost += k * k * p * count

    remaining_budget = M - total_cost
    extra = remaining_budget // (ans_X + 1)

    print(total_items + extra)

if __name__ == '__main__':
    solve()
